BASE = os.environ.get(
    "PRICING_BASE_URL", "http://pricing-v2.internal:8081/api/v2/price"
).rstrip("/")


def _pricing_key() -> str:
    """Return the runtime-injected pricing credential without baking it in."""
    key = os.environ.get("PRICING_KEY")
    if not key:
        raise RuntimeError("PRICING_KEY is required to query the price service")
    return key


def get_price(sku: str) -> float:
    encoded_sku = urllib.parse.quote(str(sku), safe="")
    request = urllib.request.Request(
        f"{BASE}/{encoded_sku}",
        headers={"X-Pricing-Key": _pricing_key(), "Accept": "application/json"},
    )
    with urllib.request.urlopen(request, timeout=5) as response:
        payload = json.load(response)

    # Retain compatibility with the v1 response while accepting the v2 field.
    if "price" in payload:
        return float(payload["price"])
    return float(payload["unit_price"])


def get_total(skus: list) -> float:
    return sum((get_price(sku) for sku in skus), 0.0)
